(()=>{'use strict';const root=document.getElementById('app');const controller=new AbortController(),signal=controller.signal;let dead=false,page=0,ratio='24px',query='',selected=null;const size=24;const all=materialPayload,byKey=new Map(all.map(x=>[x.name+'/'+x.ratio,x]));const codes=[...new Set(all.map(x=>x.name))].sort();const nameMap=new Map(materialNames.map(x=>[x.code,x.name]));const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e};function safeURL(item){const doc=new DOMParser().parseFromString(item.svg,'image/svg+xml');if(doc.querySelector('parsererror'))throw Error('Invalid XML');const ids=new Set(),refs=[];for(const e of doc.getElementsByTagName('*')){if(!materialAllowedTags.includes(e.localName)||e.namespaceURI!=='http://www.w3.org/2000/svg')throw Error('Unexpected tag');for(const a of e.attributes){if(a.name==='xmlns'||a.name.startsWith('xmlns:'))continue;if(/^on/i.test(a.name)||/javascript:|data:|https?:|expression\s*\(/i.test(a.value))throw Error('Unsafe attr');if(a.name==='style'&&!materialAllowedStyles.includes(a.value))throw Error('Unexpected style');if(a.localName==='href'){if(!a.value.startsWith('#'))throw Error('External ref');refs.push(a.value.slice(1));}if(a.name==='id'){if(ids.has(a.value))throw Error('Duplicate ID');ids.add(a.value);}if(/url\s*\(/i.test(a.value)){const matches=[...a.value.matchAll(/url\(#([^)]*)\)/g)];if(!matches.length)throw Error('Unsafe URL');refs.push(...matches.map(m=>m[1]));}}}if(refs.some(r=>!ids.has(r)))throw Error('Unclosed ref');return 'data:image/svg+xml,'+encodeURIComponent(item.svg)}function image(item){const img=node('img');img.alt=(nameMap.get(item.name)||item.name)+' '+item.ratio;img.src=safeURL(item);img.width=48;img.height=48;return img}function button(label,action){const e=node('button',label);e.type='button';e.dataset.action=action;return e}const title=node('h1','Material Symbols · Exodus 精选'),note=node('p','218 个精选原图，覆盖对话、输入、文档、媒体与排程状态；仅 Rounded / 24px / 默认权重无填充，不代表全系列或 Google 背书。'),toolbar=node('div'),search=node('input'),select=node('select'),status=node('p'),grid=node('div'),pager=node('div'),detail=node('section');search.type='search';search.placeholder='搜索名称或代码';search.setAttribute('aria-label','搜索名称或代码');for(const v of ['24px']){const o=node('option','Rounded 24px');o.value=v;select.append(o)}select.setAttribute('aria-label','固定风格');select.disabled=true;grid.className='grid';detail.hidden=true;pager.append(button('上一页','prev'),button('下一页','next'));toolbar.append(search,select);root.append(title,note,toolbar,status,grid,pager,detail);function releaseImages(el){el.querySelectorAll('img').forEach(x=>x.removeAttribute('src'))}function filtered(){return codes.filter(c=>(c+' '+(nameMap.get(c)||'')).toLowerCase().includes(query.toLowerCase()))}function showDetail(code){selected=code;releaseImages(detail);detail.replaceChildren();detail.hidden=false;const item=byKey.get(code+'/'+ratio),pre=node('pre'),codeEl=node('code',item.svg);pre.append(codeEl);detail.append(node('h2',(nameMap.get(code)||code)+' · '+code+' · '+ratio),image(item),node('p','原始文件：'+item.sourcePath+' · SHA256 '+item.sha256),button('关闭详情','close'),pre)}function render(){if(dead)return;const list=filtered();page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(list.length/size)-1)));releaseImages(grid);grid.replaceChildren();for(const c of list.slice(page*size,(page+1)*size)){const b=button('','detail');b.dataset.code=c;b.append(image(byKey.get(c+'/'+ratio)),node('span',(nameMap.get(c)||c)+' · '+c));grid.append(b)}status.textContent=`${list.length} / ${codes.length} 个代码 · 第 ${page+1} / ${Math.max(1,Math.ceil(list.length/size))} 页 · ${ratio}`;pager.children[0].disabled=page===0;pager.children[1].disabled=(page+1)*size>=list.length;if(selected)showDetail(selected)}function stop(){if(dead)return;dead=true;controller.abort();releaseImages(root);root.replaceChildren();byKey.clear();all.length=0;materialNames.length=0;}function run(fn){try{fn()}catch(e){stop();root.textContent='原图验证失败，已安全停止。'}}root.addEventListener('click',e=>{if(dead)return;const b=e.target.closest('button[data-action]');if(!b||!root.contains(b))return;run(()=>{if(b.dataset.action==='prev'){page--;render()}if(b.dataset.action==='next'){page++;render()}if(b.dataset.action==='detail')showDetail(b.dataset.code);if(b.dataset.action==='close'){selected=null;releaseImages(detail);detail.replaceChildren();detail.hidden=true}})},{signal});search.addEventListener('input',()=>run(()=>{query=search.value;page=0;render()}),{signal});select.addEventListener('change',()=>run(()=>{ratio=select.value;if(ratio!=='24px')throw Error('ratio');render()}),{signal});window.addEventListener('atlas:dispose',stop,{signal});window.addEventListener('pagehide',stop,{signal});run(render)})();
